'use strict';
const APP_LOGOS={"M17LIVE":"data:image/png;base64,","KDSPLAYER":"data:image/png;base64,","DEADPLAYER25":"data:image/png;base64,","DEADSMART":"data:image/png;base64,","IBO PLAYER":"data:image/png;base64,","SHAMELTV":"data:image/png;base64,","NANOMID":"data:image/png;base64,","VUPLAYER":"data:image/png;base64,","HOT IPTV":"data:image/png;base64,","SETIPTV":"data:image/png;base64,","TIVIMATE":"data:image/png;base64,"};
const APPS=['M17LIVE','KDSPLAYER','DEADPLAYER25','DEADSMART','IBO PLAYER','SHAMELTV','NANOMID','VUPLAYER','HOT IPTV','SETIPTV','TIVIMATE'];
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(n/100),today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()), fmt=d=>d?d.split('-').reverse().join('/'):'—';
const euro=v=>{const n=Number(String(v).replace(',','.'));if(!Number.isFinite(n)||n<0)throw Error('Introduce un importe válido.');return Math.round(n*100)};
function addMonths(date,n){let d=new Date(date+'T12:00:00Z');const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d.toISOString().slice(0,10)}
function madridParts(value){return Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]))}
function madridDate(value){const p=madridParts(value);return `${p.year}-${p.month}-${p.day}`}
function atMadridDate(date,reference){const p=madridParts(reference),[y,m,d]=date.split('-').map(Number),target=Date.UTC(y,m-1,d,+p.hour,+p.minute,+p.second);let guess=target,seen=[];for(let i=0;i<5;i++){const q=madridParts(guess),wall=Date.UTC(+q.year,+q.month-1,+q.day,+q.hour,+q.minute,+q.second),next=guess+target-wall;if(next===guess)return new Date(next).toISOString();if(seen.includes(next))return new Date(Math.max(next,guess)).toISOString();seen.push(guess);guess=next}return new Date(guess).toISOString()}
function expiryFrom(start,months){return atMadridDate(addMonths(madridDate(start),months),start)}
function dateTime(value){return new Intl.DateTimeFormat('es-ES',{timeZone:'Europe/Madrid',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(value))}
function durationFields(){return `<section class="full duration-panel"><h3>Duración</h3><div class="duration-options" role="group" aria-label="Duración inicial">${[[1,'1 mes'],[3,'3 meses'],[6,'6 meses'],[12,'1 año']].map(([n,t])=>`<button type="button" data-duration="${n}" aria-pressed="${n===1}" class="duration-choice ${n===1?'selected':''}">${t}</button>`).join('')}</div><input type="hidden" name="initialMonths" value="1"><div class="expiry-preview"><span>Expiración prevista</span><strong id="initialExpiry"></strong><small>Se calcula automáticamente al guardar</small></div></section>`}
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let records=[], current=null, busy=false, refreshPromise=null,session=null;
try{session=JSON.parse(sessionStorage.getItem('m17.session')||'null')}catch{}
const config=window.M17_CONFIG||{},url=(config.supabaseUrl||'').replace(/\/$/,'');
function notify(s){const target=$('#modal').open?$('#modal'):document.querySelector('main');target.appendChild($('#notice'));$('#notice').textContent=s;$('#notice').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').style.display='none',6500)}
function keepSession(s){session=s;if(s)sessionStorage.setItem('m17.session',JSON.stringify(s));else sessionStorage.removeItem('m17.session')}
async function raw(path,options={},token){let res=await fetch(url+path,{...options,headers:{apikey:config.supabaseKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...options.headers}});let body=await res.text();let data;try{data=JSON.parse(body)}catch{data=body}if(!res.ok){const e=Error(data.message||data.msg||data.error_description||'No se pudo completar la operación.');e.status=res.status;throw e}return data}
async function api(path,options={}){if(!session)throw Error('Inicia sesión.');if((session.expires_at||0)*1000<Date.now()+60000){if(!refreshPromise)refreshPromise=raw('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})}).then(s=>keepSession({...s,expires_at:Math.floor(Date.now()/1000)+s.expires_in})).catch(e=>{keepSession(null);showAuth();throw e}).finally(()=>refreshPromise=null);await refreshPromise}return raw(path,options,session.access_token)}
function showAuth(){const ok=!!session;$('#login').hidden=ok;$('#workspace').hidden=!ok;$('#logout').hidden=!ok;if(!ok){records=[];current=null;if($('#modal').open)$('#modal').close();$('#list').innerHTML='';$('#stats').innerHTML=''}}
async function load(){try{let all=[],offset=0;while(true){const page=await api('/rest/v1/clients?select=*&order=created_at.desc&limit=500&offset='+offset);all.push(...page);if(page.length<500)break;offset+=500}records=all;await loadMessages();render()}catch(e){notify(e.message)}}
const hasPending=d=>(d.events||[]).some(e=>e.status==='pending');
const pending=d=>(d.events||[]).filter(e=>e.status==='pending').reduce((s,e)=>s+(e.amount||0),0);
function pendingLabel(d){const items=(d.events||[]).filter(e=>e.status==='pending');if(!items.length)return 'Al corriente';const unknown=items.some(e=>e.amount==null),amount=items.reduce((sum,e)=>sum+(e.amount||0),0);return 'Pendiente de pago · '+(unknown?(amount?money(amount)+' + importe por definir':'importe por definir'):money(amount))}
function state(d){if(d.archived)return'archived';if(d.expiryAt){const ms=Date.parse(d.expiryAt)-Date.now();return ms<=0?'expired':ms<=7*86400000?'soon':'active'}const days=Math.round((Date.parse(d.expiry+'T12:00:00Z')-Date.parse(today()+'T12:00:00Z'))/86400000);return days<0?'expired':days<=7?'soon':'active'}
function badge(d){let s=state(d);return '<span class="badge '+s+'-b">'+({archived:'Archivada',expired:'Caducada',soon:'Próxima a caducar',active:'Activa'}[s])+'</span>'}
function render(){const live=records.filter(r=>!r.data.archived),month=today().slice(0,7),events=records.flatMap(r=>r.data.events||[]);$('#stats').innerHTML=[['Líneas activas',live.filter(r=>state(r.data)!=='expired').length,'Con servicio vigente'],['Próximos 7 días',live.filter(r=>state(r.data)==='soon').length,'Vencimientos a la vista'],['Cobrado este mes',money(events.filter(e=>e.status==='paid'&&e.paidDate?.startsWith(month)).reduce((s,e)=>s+(e.amount||0),0)),'Bizum y efectivo'],['Pendiente de cobro',records.filter(r=>hasPending(r.data)).length+' cliente(s)','']].map(([t,n,s])=>`<div class="stat"><span>${t}</span><strong>${n}</strong>${s?`<small>${s}</small>`:''}</div>`).join('');const q=norm($('#search').value),app=$('#appFilter').value,filter=$('#status').value;let rows=records.filter(r=>{let d=r.data;return [d.code,d.name,d.username,d.mobile].some(v=>norm(v).includes(q))&&(!app||d.apps.some(a=>a.name===app))&&(filter==='archived'?d.archived:!d.archived)&&(filter==='pending'?hasPending(d):['active','soon','expired'].includes(filter)?(filter==='active'?['active','soon'].includes(state(d)):state(d)===filter):true)});$('#count').textContent=rows.length+' fichas · '+live.length+' líneas sin archivar';$('#list').innerHTML=rows.length?rows.map(r=>{const d=r.data;return `<div class="row"><div><span class="avatar">${esc(d.name.slice(0,2).toUpperCase())}</span><strong>${esc(d.name)}</strong><small>ID ${esc(d.code)} · ${esc(d.username)}</small></div><div class="date"><strong>${d.expiryAt?dateTime(d.expiryAt):fmt(d.expiry)}</strong>${badge(d)}</div><div class="apps">${d.apps.map(a=>`<span class="badge">${esc(a.name)}</span>`).join('')}</div><div>${hasPending(d)?`<span class="badge pending-b">${esc(pendingLabel(d))}</span>`:'<small>Al corriente</small>'}</div><button class="ghost" data-open="${r.id}">Ver ficha →</button></div>`}).join(''):'<div class="empty"><b>No hay fichas que mostrar</b>Añade tu primera línea o cambia los filtros.</div>'}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function field(title,name,value='',type='text',required=true){return `<label>${title}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${name==='username'?'autocomplete="off" autocapitalize="none" spellcheck="false" data-lpignore="true" data-1p-ignore':name==='password'?'autocomplete="new-password" data-lpignore="true" data-1p-ignore':''} ${type==='number'?'min="0" step="0.01"':''}></label>`}
const methodSelect='<fieldset class="method-picker"><legend>Método de pago</legend><div class="method-options"><label class="method-button"><input type="radio" name="method" value="Bizum" checked><span>📱 Bizum</span></label><label class="method-button"><input type="radio" name="method" value="Efectivo"><span>💶 Efectivo</span></label></div></fieldset>';
function paymentFields(){return `<input type="hidden" name="status" value="paid"><div class="payment-options" role="group" aria-label="Estado del pago"><button type="button" class="payment-choice selected" data-payment="paid" aria-pressed="true"><strong>✓ Pagado</strong><span>Registrar el importe y el método</span></button><button type="button" class="payment-choice" data-payment="gift" aria-pressed="false"><strong>🎁 Regalo</strong><span>Sin cobro · 0 €</span></button><button type="button" class="payment-choice later-choice" id="later" data-payment="pending" aria-pressed="false"><strong>◷ Paga más tarde</strong><span>Importe pendiente por definir</span></button></div><div class="grid">${field('Importe (€)','amount','','text')}${methodSelect}</div>`}
function wirePayment(){const f=$('#operationForm'),s=f.elements.status,a=f.elements.amount,m=f.querySelector('.method-picker');const update=()=>{a.disabled=s.value!=='paid';a.required=s.value==='paid';a.closest('label').hidden=s.value!=='paid';m.hidden=s.value!=='paid';m.querySelectorAll('input').forEach(input=>input.disabled=s.value!=='paid');f.querySelectorAll('[data-payment]').forEach(b=>{const selected=b.dataset.payment===s.value;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})};f.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>{s.value=b.dataset.payment;update()});update()}
async function save(data,row){if(row){const result=await api('/rest/v1/clients?id=eq.'+row.id+'&revision=eq.'+row.revision,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({data,revision:row.revision+1})});if(!result.length)throw Error('Esta ficha cambió en otro dispositivo. Cierra y pulsa Actualizar antes de editar de nuevo.');records=records.map(r=>r.id===row.id?result[0]:r);current=result[0]}else{const result=await api('/rest/v1/clients',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({owner_id:session.user.id,data})});records.unshift(result[0]);current=result[0]}render()}
function eventFrom(f,type,from,to,months){const status=f.get('status');if(!['paid','pending','gift'].includes(status))throw Error('Selecciona el estado del pago.');const amount=status==='gift'?0:status==='pending'?null:euro(f.get('amount'));if(status==='paid'&&amount<=0)throw Error('Para importe 0 selecciona Regalo.');return {id:crypto.randomUUID(),type,status,amount,method:status==='paid'?f.get('method'):null,date:today(),paidDate:status==='paid'?today():null,from,to,months,note:f.get('eventNote')||''}}
async function action(fn){if(busy)return;busy=true;$('#modalBody').querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn()}catch(e){notify(e.message)}finally{busy=false;$('#modalBody').querySelectorAll('button').forEach(b=>b.disabled=b.id==='renew'&&!!current?.data.archived)}}
function edit(row=null){const d=row?.data||{};modal(row?'Editar cliente':'Nuevo Cliente',`<form id="operationForm" autocomplete="off"><div class="grid">${field('ID de usuario','code',d.code)}${field('Nombre de la persona','name',d.name)}${field('Usuario','username',d.username)}${field('Contraseña','password',d.password,'password')}${field('Móvil','mobile',d.mobile,'tel',false)}${row?field('Fecha de alta','start',d.start||today(),'date')+field('Fecha de expiración','expiry',d.expiry||addMonths(today(),1),'date'):durationFields()}<label class="full">Notas generales<textarea name="notes">${esc(d.notes||'')}</textarea></label></div><h3>Aplicaciones instaladas</h3><p>Toca una tarjeta para añadir o quitar la aplicación.</p><div id="appEditor" class="app-picker">${APPS.map(name=>{const a=d.apps?.find(a=>a.name===name);return `<div class="app-card app-option"><label class="app-toggle"><input type="checkbox" name="apps" value="${esc(name)}" ${a?'checked':''}><span class="app-symbol"><img class="app-logo" src="${APP_LOGOS[name]}" alt="" draggable="false"></span><span class="app-caption"><strong>${esc(name)}</strong><span>${APPS.indexOf(name)<4?'Oficial del servicio':'Aplicación externa'}</span></span><span class="app-check" aria-hidden="true"></span></label>${APPS.indexOf(name)<4?'':`<textarea aria-label="Notas de ${esc(name)}" data-app="${esc(name)}" placeholder="MAC, número de serie, dispositivo…">${esc(a?.notes||'')}</textarea>`}</div>`}).join('')}</div>${!row?'<h3>Pago del alta</h3>'+paymentFields():''}<div class="actions"><button>Guardar cliente</button><button type="button" class="ghost" data-cancel>Cancelar</button></div></form>`);$('#appEditor').querySelectorAll('input').forEach(c=>{const t=c.closest('.app-card').querySelector('textarea');if(t){t.hidden=!c.checked;c.onchange=()=>t.hidden=!c.checked}});if(!row){wirePayment();const form=$('#operationForm');const preview=()=>$('#initialExpiry').textContent=dateTime(expiryFrom(new Date(),Number(form.elements.initialMonths.value)));form.querySelectorAll('[data-duration]').forEach(b=>b.onclick=()=>{form.elements.initialMonths.value=b.dataset.duration;form.querySelectorAll('[data-duration]').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected))});preview()});preview();for(const name of ['username','password']){const input=$('#operationForm').elements[name];input.value='';input.readOnly=true;const unlock=()=>{input.readOnly=false};input.addEventListener('focus',unlock,{once:true});input.addEventListener('pointerdown',unlock,{once:true})}}$('#operationForm').onsubmit=e=>{e.preventDefault();action(async()=>{const f=new FormData(e.target),code=f.get('code').trim(),name=f.get('name').trim(),username=f.get('username').trim();if(!code||!name||!username||!f.get('password').trim())throw Error('Completa ID, nombre, usuario y contraseña de la línea.');if(row&&f.get('expiry')<f.get('start'))throw Error('La expiración no puede ser anterior al alta.');const createdNow=new Date().toISOString(),initialMonths=Number(f.get('initialMonths')||1),expiryAt=!row?expiryFrom(createdNow,initialMonths):d.expiryAt&&f.get('expiry')!==d.expiry?atMadridDate(f.get('expiry'),d.expiryAt):d.expiryAt;const data={...d,code,name,username,password:f.get('password'),mobile:f.get('mobile').trim(),start:row?f.get('start'):madridDate(createdNow),expiry:row?f.get('expiry'):madridDate(expiryAt),...(!row?{startedAt:createdNow,initialMonths}:{}),...(expiryAt?{expiryAt}:{}),notes:f.get('notes'),apps:f.getAll('apps').map(name=>({name,notes:APPS.indexOf(name)<4?'':([...e.target.querySelectorAll('[data-app]')].find(t=>t.dataset.app===name)?.value||'')})),archived:d.archived||false,events:d.events||[]};if(!row)data.events=[{...eventFrom(f,'alta',null,data.expiry,initialMonths),toAt:expiryAt,createdAt:createdNow}];await save(data,row);detail(current);notify('Ficha guardada')})}}
async function deleteClient(row){const d=row.data;if(!confirm(`¿Seguro que quieres eliminar este cliente?\n\n${d.name} · ID ${d.code}\n\nSe borrarán esta línea y todo su historial de pagos, renovaciones y regalos. Los totales también se actualizarán. Esta acción no se puede deshacer.`))return;await action(async()=>{let result;try{result=await api('/rest/v1/clients?id=eq.'+row.id+'&revision=eq.'+row.revision,{method:'DELETE',headers:{Prefer:'return=representation'}})}catch(e){if(e.status===403)throw Error('Falta habilitar el borrado en Supabase. Ejecuta habilitar_eliminar.sql y vuelve a intentarlo.');throw e}if(!Array.isArray(result)||result.length!==1)throw Error('No se ha eliminado: la ficha cambió o ya no existe. Cierra y pulsa Actualizar antes de intentarlo de nuevo.');records=records.filter(r=>r.id!==row.id);current=null;render();$('#modal').close();notify('Cliente eliminado')})}
const MESSAGE_TITLES={access:'🔑 Datos de acceso',renewal:'🎉 Renovación completada',expiry:'⏰ Aviso de caducidad'};
const DEFAULT_MESSAGES={
 access:'¡Hola, {nombre}! 👋\n\n📺 Aquí tienes tus datos de acceso:\n\n👤 Usuario: {usuario}\n🔑 Contraseña: {contraseña}\n🔞 Código de adultos: 0000\n📅 Tu cuenta caduca el {caducidad}.\n\n🍿 ¡Todo listo para disfrutar! Si necesitas ayuda, escríbeme 😊',
 renewal:'¡Hola, {nombre}! 👋\n\n✅ ¡Tu renovación ya está completada! 🎉\n\n📅 Tu cuenta está activa hasta el {caducidad}.\n\n📲 Me pondré en contacto contigo 15 días antes de que expire tu cuenta, para que puedas renovar con tiempo.\n\n🍿 ¡A seguir disfrutando! Muchas gracias por seguir conmigo 😊',
 expiry:'¡Hola, {nombre}! 👋\n\n{aviso_caducidad}\n📅 Fecha de caducidad: {caducidad}.\n\n🔄 Si quieres renovarla, respóndeme por aquí y lo dejamos preparado.\n\n🍿 ¡Que no se te quede el plan a medias! 😊'
};
let messageSettings=null, messagesReady=false;
async function loadMessages(){try{const rows=await api('/rest/v1/message_settings?select=*');messageSettings=rows[0]||null;messagesReady=true}catch{messageSettings=null;messagesReady=false}}
function messageTemplate(type){return messageSettings?.templates?.[type]||DEFAULT_MESSAGES[type]}
function validateTemplate(type,text){if(!text.trim())throw Error('La plantilla no puede estar vacía.');if(text.length>10000)throw Error('El mensaje es demasiado largo (máximo 10.000 caracteres).');const allowed=['nombre','id','caducidad',...(type==='access'?['usuario','contraseña']:[]),...(type==='renewal'?['fecha_inicio','fecha_fin']:[]),...(type==='expiry'?['aviso_caducidad']:[])];for(const match of text.matchAll(/\{([^{}]+)\}/g))if(!allowed.includes(match[1]))throw Error('Campo no válido para este mensaje: '+match[0]);}
function quickMessage(d,type){
 let template=messageTemplate(type);
 // A malformed saved template must never make the copy button do nothing.
 try{validateTemplate(type,template)}catch{template=DEFAULT_MESSAGES[type]}
 const values={nombre:d.name,id:d.code,usuario:d.username,contraseña:d.password,caducidad:fmt(d.expiry),fecha_inicio:fmt(d.start),fecha_fin:fmt(d.expiry),aviso_caducidad:state(d)==='expired'?'⌛ Tu cuenta ha caducado':'⏰ ¡Tu cuenta está próxima a caducar!'};
 if(type==='renewal')template=template.replace('📆 Periodo renovado: del {fecha_inicio} al {fecha_fin}.','📅 Tu cuenta está activa hasta el {caducidad}.');
 if(type==='access'&&!template.includes('🔞 Código de adultos: 0000'))template+='\n\n🔞 Código de adultos: 0000';
 return template.replace(/\{([^{}]+)\}/g,(_,key)=>String(values[key]??''));
}
async function copyQuickMessage(row,type){let text;try{text=quickMessage(row.data,type)}catch(e){notify(e.message);return}try{await navigator.clipboard.writeText(text);notify('¡Mensaje copiado! Pégalo en WhatsApp 😊')}catch{modal(MESSAGE_TITLES[type],'<p>Tu navegador no ha permitido copiar directamente. Mantén pulsado el texto para copiarlo.</p><textarea id="quickMessageText" class="quick-message-text" aria-label="Mensaje para copiar" readonly></textarea><div class="actions"><button class="ghost" data-cancel>Volver a la ficha</button></div>');$('#quickMessageText').value=text;$('#quickMessageText').focus();$('#quickMessageText').select()}}
async function editMessageTemplates(row){
 await loadMessages();if(!messagesReady){notify('Para guardar plantillas, ejecuta habilitar_mensajes.sql en Supabase y vuelve a intentarlo.');return}
 const snapshot=messageSettings;
 modal('✏️ Editar plantillas',`<form id="templatesForm"><p>Estos textos se usarán para todos tus clientes, también en tus otros dispositivos. Los campos entre llaves se rellenan automáticamente al copiar.</p>${Object.entries(MESSAGE_TITLES).map(([type,title])=>`<label>${title}<small>Campos: {nombre}, {id}, {caducidad}${type==='access'?', {usuario}, {contraseña}':type==='renewal'?', {fecha_inicio}, {fecha_fin}':', {aviso_caducidad}'}</small><textarea name="${type}" class="quick-message-text" maxlength="10000" required></textarea></label><button type="button" class="ghost" data-default-message="${type}">Restaurar texto original</button>`).join('')}<p>🔞 El mensaje de acceso incluirá siempre «Código de adultos: 0000». El aviso de contacto no programa recordatorios automáticos.</p><div class="actions"><button>Guardar plantillas</button><button type="button" class="ghost" data-cancel>Cancelar</button></div></form>`);
 const form=$('#templatesForm');Object.keys(MESSAGE_TITLES).forEach(type=>form.elements[type].value=messageTemplate(type));form.querySelectorAll('[data-default-message]').forEach(b=>b.onclick=()=>form.elements[b.dataset.defaultMessage].value=DEFAULT_MESSAGES[b.dataset.defaultMessage]);
 form.onsubmit=e=>{e.preventDefault();action(async()=>{const templates={};for(const type of Object.keys(MESSAGE_TITLES)){templates[type]=form.elements[type].value.trim();validateTemplate(type,templates[type])}const result=await api('/rest/v1/message_settings'+(snapshot?'?owner_id=eq.'+session.user.id+'&revision=eq.'+snapshot.revision:''),{method:snapshot?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(snapshot?{templates,revision:snapshot.revision+1}:{owner_id:session.user.id,templates,revision:1})});if(!Array.isArray(result)||result.length!==1)throw Error('Las plantillas cambiaron en otro dispositivo. Cancela y vuelve a abrir el editor antes de guardar.');messageSettings=result[0];detail(row);notify('¡Plantillas guardadas para todos tus clientes! 😊')})};
}
function detail(row){current=row;const d=row.data,ev=d.events||[],paid=ev.filter(e=>e.status==='paid').reduce((s,e)=>s+(e.amount||0),0),ren=ev.filter(e=>e.type==='renovacion'&&e.status!=='gift').length,gifts=ev.filter(e=>e.status==='gift').reduce((s,e)=>s+(e.months||0),0);modal(d.name,`<div>${badge(d)} ${hasPending(d)?'<span class="badge pending-b">'+esc(pendingLabel(d))+'</span>':''}</div><dl class="details grid"><div><dt>ID de usuario</dt><dd>${esc(d.code)}</dd><dt>Usuario</dt><dd>${esc(d.username)}</dd><dt>Contraseña</dt><dd><span id="secret">••••••••</span> <button id="reveal" class="ghost">Mostrar</button></dd></div><div><dt>Móvil</dt><dd>${esc(d.mobile)||'—'}</dd><dt>Expiración</dt><dd>${d.expiryAt?dateTime(d.expiryAt):fmt(d.expiry)}</dd><dt>Fecha de alta</dt><dd>${d.startedAt?dateTime(d.startedAt):fmt(d.start)}</dd></div></dl><p><b>${ren}</b> renovaciones · <b>${gifts}</b> meses regalados · <b>${money(paid)}</b> cobrados · <b>${esc(pendingLabel(d))}</b></p><div class="actions"><button id="renew" ${d.archived?'disabled':''}>Renovar</button><button id="edit" class="ghost">Editar ficha</button><button id="archive" class="${d.archived?'ghost':'danger'}">${d.archived?'Restaurar':'Archivar'}</button><button id="deleteClient" class="danger">Eliminar cliente</button></div><section class="quick-messages"><div class="quick-messages-heading"><h3>💬 Mensajes rápidos</h3><button type="button" id="editMessageTemplates" class="quick-template-edit" aria-label="Editar plantillas de mensajes" title="Editar plantillas"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m16 3 5 5M4 15 16 3a2.1 2.1 0 0 1 5 5L9 20l-6 1z"/></svg></button></div><p>Toca un mensaje para copiarlo directamente con los datos de este cliente.</p><div class="quick-message-buttons"><button class="quick-message-option" data-quick-message="access"><strong>🔑 Datos de acceso</strong><span>Usuario, contraseña y código de adultos</span></button><button class="quick-message-option" data-quick-message="renewal"><strong>🎉 Renovación completada</strong><span>Periodo renovado y próximo contacto</span></button><button class="quick-message-option" data-quick-message="expiry"><strong>⏰ Aviso de caducidad</strong><span>Fecha de vencimiento de su cuenta</span></button></div></section><h3>Aplicaciones y notas</h3>${d.apps.map((a,i)=>`<div class="app-card"><strong>${esc(a.name)}</strong>${APPS.indexOf(a.name)<4?'':`<p>${esc(a.notes)||'Sin notas de instalación'}</p><button class="ghost" data-edit-app="${i}">Editar notas</button>`}</div>`).join('')||'<p>Sin aplicaciones asignadas.</p>'}<h3>Notas generales</h3><p style="white-space:pre-wrap">${esc(d.notes)||'Sin notas.'}</p><h3>Historial de operaciones</h3>${[...ev].reverse().map(e=>`<div class="event"><div><strong>${e.status==='gift'?'🎁 Regalo':e.type==='alta'?'Alta':'Renovación'} · ${e.amount===null?'Importe por definir':money(e.amount)}</strong><p>${fmt(e.date)} ${e.months?'· '+e.months+' meses':''} · ${e.status==='pending'?'Pendiente':e.status==='gift'?'Sin cobro':esc(e.method)+' · cobrado '+fmt(e.paidDate)}</p><p>Vencimiento: ${e.fromAt?dateTime(e.fromAt):fmt(e.from)} → ${e.toAt?dateTime(e.toAt):fmt(e.to)}</p>${e.note?'<p>'+esc(e.note)+'</p>':''}</div>${e.status==='pending'?`<button class="ghost" data-pay="${e.id}">Registrar cobro</button>`:''}</div>`).join('')}`);$('#modalBody').querySelectorAll('[data-quick-message]').forEach(b=>b.onclick=()=>copyQuickMessage(row,b.dataset.quickMessage));$('#editMessageTemplates').onclick=()=>editMessageTemplates(row);$('#reveal').onclick=()=>{let b=$('#reveal'),show=b.textContent==='Mostrar';$('#secret').textContent=show?d.password:'••••••••';b.textContent=show?'Ocultar':'Mostrar'};$('#deleteClient').onclick=()=>deleteClient(row);$('#edit').onclick=()=>edit(row);$('#renew').onclick=()=>renew(row);$('#archive').onclick=()=>{if(confirm(d.archived?'¿Restaurar esta ficha?':'¿Archivar esta ficha? Se conservarán los pagos y el historial.'))action(async()=>{await save({...d,archived:!d.archived},row);detail(current)})}}
function renewalExpiry(d,months){if(![1,3,6,12].includes(months))throw Error('Selecciona los meses a renovar.');const expiryAt=d.expiryAt?expiryFrom(d.expiryAt,months):null;return {expiry:expiryAt?madridDate(expiryAt):addMonths(d.expiry,months),expiryAt}}
function renew(row){
 const d=row.data;
 modal('Renovar',`<form id="operationForm"><p>${esc(d.name)} · Vence el ${fmt(d.expiry)}</p><section class="duration-panel"><h3>Meses a renovar</h3><div class="duration-options" role="group" aria-label="Meses a renovar">${[[1,'1 mes'],[3,'3 meses'],[6,'6 meses'],[12,'1 año']].map(([n,t])=>`<button type="button" data-renew-months="${n}" aria-pressed="${n===1}" class="duration-choice ${n===1?'selected':''}">${t}</button>`).join('')}</div><input type="hidden" name="months" value="1"><p id="newExpiry"></p></section>${paymentFields()}<div class="actions"><button>Guardar operación</button><button type="button" data-cancel class="ghost">Cancelar</button></div></form>`);
 wirePayment();const f=$('#operationForm');
 const preview=()=>{const next=renewalExpiry(d,Number(f.elements.months.value));$('#newExpiry').textContent='Nuevo vencimiento: '+fmt(next.expiry)};
 f.querySelectorAll('[data-renew-months]').forEach(b=>b.onclick=()=>{f.elements.months.value=b.dataset.renewMonths;f.querySelectorAll('[data-renew-months]').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected))});preview()});preview();
 f.onsubmit=e=>{e.preventDefault();action(async()=>{const fd=new FormData(f),months=Number(fd.get('months')),next=renewalExpiry(d,months),event={...eventFrom(fd,'renovacion',d.expiry,next.expiry,months),periodStart:d.expiry,...(next.expiryAt?{fromAt:d.expiryAt,toAt:next.expiryAt}:{})};await save({...d,expiry:next.expiry,...(next.expiryAt?{expiryAt:next.expiryAt}:{}),events:[...(d.events||[]),event]},row);detail(current);notify(event.status==='pending'?'Renovación guardada · cliente pendiente de pago':event.status==='gift'?'Regalo registrado':'Renovación y cobro registrados')})};
}
$('#modalBody').addEventListener('click',e=>{const cancel=e.target.closest('[data-cancel]');if(cancel){if(current)detail(current);else $('#modal').close()}const ae=e.target.closest('[data-edit-app]');if(ae){const row=current,i=Number(ae.dataset.editApp);modal('Editar notas · '+row.data.apps[i].name,`<form id="noteForm"><label>Notas de instalación<textarea name="notes">${esc(row.data.apps[i].notes)}</textarea></label><div class="actions"><button>Guardar notas</button><button type="button" class="ghost" data-cancel>Cancelar</button></div></form>`);$('#noteForm').onsubmit=e=>{e.preventDefault();action(async()=>{const apps=structuredClone(row.data.apps);apps[i].notes=new FormData(e.target).get('notes');await save({...row.data,apps},row);detail(current)})}}const pay=e.target.closest('[data-pay]');if(pay){const row=current,id=pay.dataset.pay,event=row.data.events.find(x=>x.id===id);modal('Registrar cobro',`<form id="payForm"><p>${esc(row.data.name)} · ${event.amount===null?'Importe por definir':money(event.amount)}</p><div class="grid">${event.amount===null?field('Importe cobrado (€)','amount','','text'):''}${methodSelect}</div><div class="actions"><button>Confirmar cobro</button><button type="button" class="ghost" data-cancel>Cancelar</button></div></form>`);$('#payForm').onsubmit=e=>{e.preventDefault();action(async()=>{const f=new FormData(e.target),amount=event.amount===null?euro(f.get('amount')):event.amount;if(amount<=0)throw Error('Introduce el importe cobrado.');const events=row.data.events.map(x=>x.id===id?{...x,amount,status:'paid',method:f.get('method'),paidDate:today()}:x);await save({...row.data,events},row);detail(current);notify('Cobro registrado')})}}});
$('#list').onclick=e=>{const b=e.target.closest('[data-open]');if(b)detail(records.find(r=>r.id===b.dataset.open))};
$('#close').onclick=()=>{if(!busy&&confirm('¿Cerrar la ficha? Los cambios sin guardar se perderán.'))$('#modal').close()};$('#modal').addEventListener('cancel',e=>{e.preventDefault();$('#close').click()});
$('#new').onclick=()=>{current=null;edit()};$('#reload').onclick=load;$('#search').oninput=render;$('#status').onchange=render;$('#appFilter').onchange=render;
$('#appFilter').innerHTML='<option value="">Todas las aplicaciones</option>'+APPS.map(a=>`<option>${a}</option>`).join('');
$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target),s=await raw('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});keepSession({...s,expires_at:Math.floor(Date.now()/1000)+s.expires_in});e.target.reset();showAuth();await load()}catch(e){notify(e.message)}finally{b.disabled=false}};
$('#logout').onclick=async()=>{try{await api('/auth/v1/logout',{method:'POST'})}catch{}keepSession(null);showAuth()};
showAuth();if(!url||!config.supabaseKey){$('#setupText').textContent='La app está preparada. Completa config.js con la URL y la clave publicable de tu proyecto de Supabase siguiendo INSTRUCCIONES.md.';$('#loginForm').querySelector('button').disabled=true}else if(config.supabaseKey.startsWith('sb_secret_')){$('#setupText').textContent='Configuración incorrecta: utiliza una clave publicable, nunca una clave secreta.';$('#loginForm').querySelector('button').disabled=true}else if(session)load();
